  ('g4-c6-l3', 'g4-c6', 'Bài 3: Ôn tập về phân số & Các phép tính phân số', 'learn', 'Rút gọn, quy đồng, cộng trừ nhân chia phân số', 2, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Phân số là trọng tâm số một của học kì 2! Cùng làm bài kiểm tra phân số nhé! 🍰"}},{"type":"concept","content":{"fractionBar":{"rows":[{"parts":6,"shaded":3,"extra":2,"label":"1/2 + 1/3 = 3/6 (xanh) + 2/6 (hồng) = 5/6"},{"parts":12,"shaded":8,"groups":4,"label":"8 ô nhỏ trong 12 ô nhỏ = 2 ô lớn trong 3 ô lớn"},{"parts":3,"shaded":2,"label":"gộp 4 ô nhỏ thành 1 ô lớn ⇒ 8/12 = 2/3"}],"label":"Quy đồng mẫu số: 1/2 = 3/6 · 1/3 = 2/6 ⇒ 1/2 + 1/3 = 3/6 + 2/6 = 5/6; gộp 4 ô nhỏ thành 1 ô lớn thì 8/12 = 2/3"},"badge":"Kiến Thức Trọng Tâm","title":"Ôn tập về phân số & Các phép tính phân số","explanation":"Ôn lại phân số và bốn phép tính với phân số.","points":["Rút gọn phân số: chia cả tử số và mẫu số cho cùng một số.","Cộng, trừ phân số cùng mẫu: cộng, trừ tử số rồi giữ nguyên mẫu số.","Nhân phân số: nhân tử số với tử số, mẫu số với mẫu số."],"rule":"Khác mẫu số thì phải quy đồng mẫu số trước khi cộng hoặc trừ."}},{"type":"quiz","content":{"question":"Tính: 3/4 + 1/2 = ?","options":["5/4","4/6","1","3/8"],"answer":"5/4","mascotHint":"3/4 + 2/4 = 5/4!"}},{"type":"quiz","content":{"question":"Tính: 2/5 × 10 = ?","options":[4,5,20,2],"answer":4,"mascotHint":"(2 × 10) : 5 = 20 : 5 = 4!"}},{"type":"summary","content":{"title":"Ôn tập phân số:","points":["Nhớ rút gọn kết quả về phân số tối giản."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g4-c6-l4', 'g4-c6', 'Bài 4: Ôn tập về hình học', 'learn', 'Chu vi và diện tích hình vuông, hình chữ nhật, hình bình hành, hình thoi', 3, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Tổng kết 4 công thức diện tích quan trọng nhất lớp 4! 📐"}},{"type":"visual","content":{"text":"- Hình chữ nhật: S = a × b - Hình vuông: S = a × a - Hình bình hành: S = a × h - Hình thoi: S = (m × n) : 2","planeShape":{"kind":"parallelogram","labels":["đáy a","chiều cao h"],"formula":"S = a × h"}}},{"type":"visual","content":{"text":"Ôn tập hình học","table":{"headers":["Hình","Công thức diện tích"],"rows":[["Hình chữ nhật","S = a × b"],["Hình vuông","S = a × a"],["Hình bình hành","S = a × h"],["Hình thoi","S = (m × n) : 2"]],"label":"Ôn tập hình học"}}},{"type":"quiz","content":{"question":"Một thửa ruộng hình bình hành có đáy 20 m và chiều cao 15 m. Diện tích thửa ruộng là:","options":["300 m²","150 m²","70 m²","350 m²"],"answer":"300 m²","mascotHint":"S = a × h = 20 × 15 = 300 m²!"}},{"type":"summary","content":{"title":"Ghi nhớ công thức hình học:","points":["Hình bình hành: S = đáy × cao.","Hình thoi: S = tích 2 đường chéo : 2."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
